test('explicit anchor repair is receipt-bound through inspection, translation and cached replay; unknown anchors accept no source',async()=>{
 for(const versioned of [false,true])for(const invalid of [false,true]){
  const files=[{path:'cli.py',content:'# original\n'}],isolation={uid:65534,interfaces:['lo'],capEff:'0000000000000000',rootReadOnly:true,modelMountReadOnly:true,memoryMaxBytes:40*1024**3,swapMaxBytes:0,cpuLimit:6},reasoning={enabled:false,effort:'none',tokenBudget:0,observed:false,characterCount:0,sha256:null};
  const s=fixture({modelOptions:{resourceProfile:'qwen3-next80b-cpu-v1',modelId:'Qwen3-Coder-Next-Q3_K_M',modelVolume:'numaron-next80b-'+ 'b'.repeat(16),repairEditProtocol:'inspection-anchors-v1'},probe:{isolation,reasoningConfig:{enabled:false,effort:'none',tokenBudget:0,cacheType:'f16'}},receipt:{isolation,reasoning},modelPatch:{baseFilesDigest:digest(files),patches:[{path:'cli.py',anchorId:invalid?'unknown':'s0',replacement:'# model correction\n'}]}});
  try{
   assert.equal(await s.model.probe(),true);const {inputDigest:unused,requestId:ignored,...body}=request(s.model);Object.assign(body,{phase:'repair',files,design:{components:[{path:'cli.py'}]},outputFormat:'exact-patches-v1',repairProtocol:'inspect-and-patch-v2',repairTools:'contextual-v1',repairInspection:'selected-source-only-v1',repairPolicy:'effective-edits-v1',repairEditProtocol:'inspection-anchors-v1',...(versioned?{privacy:'synthetic',repairAnchorPolicy:'unique-lines-v1',repairDiagnosticsPolicy:'syntax-aware-v2'}:{})});const inputDigest=digest(body),r={...body,inputDigest,requestId:digest([body.scopeDigest,inputDigest])},result=await s.model.infer(r);
   assert.equal(await s.model.verifyReceipt(result,r),true);if(invalid){assert.deepEqual(result.output.files,[]);assert.match(result.output.modelOutputError.message,/anchor/i);}else assert.deepEqual(result.output.files,[{path:'cli.py',content:'# model correction\n'}]);
   const count=s.calls.length;assert.deepEqual(await s.model.reconcile(r),result);assert.equal(s.calls.length,count);assert.equal(s.model.binding.repairEditProtocol,'inspection-anchors-v1');assert.equal(files[0].content,'# original\n');
  }finally{s.close();}
 }
});
