test('real execution receipts bind every independently generated file and reject aggregate tampering',async()=>{const s=fixture();try{await s.model.probe();const initial=request(s.model);const {inputDigest:discard,requestId:ignore,...body}=initial;Object.assign(body,{phase:'implement',design:{components:[{path:'cli.py'},{path:'core.py'}]},files:[]});const inputDigest=digest(body),r={...body,inputDigest,requestId:digest([body.scopeDigest,inputDigest])};const result=await s.model.infer(r);assert.equal(result.receipt.mode,'per-file');assert.equal(result.receipt.executions.length,2);assert.deepEqual(result.output.files.map(f=>f.path),['cli.py','core.py']);assert.equal(await s.model.verifyReceipt(result,r),true);const before=s.calls.length;assert.deepEqual(await s.model.reconcile(r),result);assert.equal(s.calls.length,before);result.output.files[1].content='forged';assert.equal(await s.model.verifyReceipt(result,r),false);}finally{s.close();}});
test('an uncertain file call preserves completed file evidence without blind redispatch',async()=>{const s=fixture({failPath:'core.py'});try{await s.model.probe();const initial=request(s.model),{inputDigest:discard,requestId:ignore,...body}=initial;Object.assign(body,{phase:'implement',design:{components:[{path:'cli.py'},{path:'core.py'}]},files:[]});const inputDigest=digest(body),r={...body,inputDigest,requestId:digest([body.scopeDigest,inputDigest])};await assert.rejects(s.model.infer(r));const journal=JSON.parse(fs.readFileSync(path.join(s.directory,r.requestId+'.json')));assert.equal(journal.steps.length,1);assert.equal(journal.status,'failed');assert(journal.failure.message.includes('synthetic'));const before=s.calls.length;assert.equal(await s.model.reconcile(r),null);await assert.rejects(s.model.infer(r),/reconcil/i);assert.equal(s.calls.length,before);}finally{s.close();}});

