test('explicit confirmed local cancellation can resume remaining components without regenerating verified files',async()=>{const s=fixture({cancelPath:'core.py'});try{await s.model.probe();const initial=request(s.model),{inputDigest:discard,requestId:ignore,...body}=initial;Object.assign(body,{phase:'implement',design:{components:[{path:'cli.py'},{path:'core.py'}]},files:[]});const inputDigest=digest(body),r={...body,inputDigest,requestId:digest([body.scopeDigest,inputDigest])};await assert.rejects(s.model.infer(r));const stored=JSON.parse(fs.readFileSync(path.join(s.directory,r.requestId+'.json')));const stopped=s.calls.find(c=>c.args[0]==='run'&&JSON.parse(c.opts.input).payload?.messages[1]?.content.includes('"generationTarget":"core.py"'));const container=stopped.args.find(a=>a.startsWith('--name=')).slice(7);await s.model.authorizeContinuation(r,{scope:'offline-development-cancelled-generation',container,producerExited:true,requestDigest:digest(r),prefixDigest:digest(stored.steps)});const result=await s.model.reconcile(r);assert.equal(await s.model.verifyReceipt(result,r),true);assert.deepEqual(result.output.files.map(f=>f.path),['cli.py','core.py']);const generations=s.calls.filter(c=>c.args[0]==='run'&&JSON.parse(c.opts.input).op==='generate').map(c=>JSON.parse(JSON.parse(c.opts.input).payload.messages[1].content).generationTarget);assert.deepEqual(generations,['cli.py','core.py','core.py']);}finally{s.close();}});

