test('cancelled continuation refuses nonempty output, live containers and mismatched authority',async()=>{
 for(const variation of ['output','live','authority']){
  const s=fixture({cancelPath:'core.py',...(variation==='live'?{containerExistsCode:0}:{})});try{
   await s.model.probe();const initial=request(s.model),{inputDigest:discard,requestId:ignore,...body}=initial;Object.assign(body,{phase:'implement',design:{components:[{path:'cli.py'},{path:'core.py'}]},files:[]});const inputDigest=digest(body),r={...body,inputDigest,requestId:digest([body.scopeDigest,inputDigest])};await assert.rejects(s.model.infer(r));
   const record=JSON.parse(fs.readFileSync(path.join(s.directory,r.requestId+'.json'))),file=fs.readdirSync(path.join(s.directory,'executions')).find(n=>JSON.parse(fs.readFileSync(path.join(s.directory,'executions',n))).code===137),container=file.slice(0,-5);
   const authorization={scope:'offline-development-cancelled-generation',container,producerExited:true,requestDigest:digest(r),prefixDigest:digest(record.steps)};
   if(variation==='output'){const p=path.join(s.directory,'executions',file),e=JSON.parse(fs.readFileSync(p));e.stdout='unconfirmed result';fs.writeFileSync(p,JSON.stringify(e));}
   if(variation==='authority')authorization.requestDigest='0'.repeat(64);
   await assert.rejects(s.model.authorizeContinuation(r,authorization));assert.equal(await s.model.reconcile(r),null);
  }finally{s.close();}
 }
});

